import{_ as a,o as i,c as e,a3 as c}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"针对理想系统的压缩算法","description":"","frontmatter":{"translationSource":{"title":"针对理想系统的压缩算法","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/compression-algorithms-for-implementing-idealized-systems"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/compression-algorithms-for-implementing-idealized-systems"}]]},"headers":[],"relativePath":"zh/compression-algorithms-for-implementing-idealized-systems.md","filePath":"zh/page-ZllGoCkftlEvd5lMExXrO2.md"}'),t={name:"zh/compression-algorithms-for-implementing-idealized-systems.md"};function p(o,s,l,d,r,g){return i(),e("div",null,[...s[0]||(s[0]=[c('<div class="logistics-content"><h1 id="针对理想系统的压缩算法" tabindex="-1">针对理想系统的压缩算法 <a class="header-anchor" href="#针对理想系统的压缩算法" aria-label="Permalink to &quot;针对理想系统的压缩算法&quot;">​</a></h1><blockquote><p>源页面 ID：<code>ZllGoCkftlEvd5lMExXrO2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=ZllGoCkftlEvd5lMExXrO2" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><blockquote><p>人脑搭产线就是在用启发式算法</p><p>——恒星泰斗</p></blockquote><p><span id="source-block-wW6QHfP1USjLEMladjHekj"></span></p><h3 id="人类是怎么布局的" tabindex="-1">人类是怎么布局的？ <a class="header-anchor" href="#人类是怎么布局的" aria-label="Permalink to &quot;人类是怎么布局的？&quot;">​</a></h3><p><span id="source-block-uaL3SZXJvWRi8tCAOsKjg9"></span></p><h4 id="以-325-799-为例" tabindex="-1">以 325/799 为例 <a class="header-anchor" href="#以-325-799-为例" aria-label="Permalink to &quot;以 325/799 为例&quot;">​</a></h4><p><span id="source-block-kFyTivAiZwVCBBDDmZ3OQJ"></span></p><h5 id="草稿-draft" tabindex="-1">草稿（Draft） <a class="header-anchor" href="#草稿-draft" aria-label="Permalink to &quot;草稿（Draft）&quot;">​</a></h5><p>话不多说我们先上 TopoFlow 图。最开始我们一般会拿到一个杂乱无章的图：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b26da58bb5f04a11.q90-d24c93e9df94f8ff.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="DdSBxHf2fCU3iPzs7yPfuW"><p>！？325/799？！</p></div><p>第一步我们会对图进行整理，使得它的平面化“看起来”相对容易，例如这样：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9e959ae217340ca1.q90-a0b813a9e8f78bb0.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="TMveqqiN4IZUgY7ToSXerV"><p>整理后的 325/799</p></div><p>我们可以称这样的一个粗布局为 Draft，观察这个 Draft，我们可以看到几个特征：</p><ol><li><p>出现了长串的分流器链条（主轴）</p></li><li><p>两侧分布回流汇流器</p></li><li><p>找到了较为合适的源、汇位置</p></li><li><p>节点之前的布线看起来较为轻松、交叉较少、每个节点/主轴的连接较为均匀</p></li></ol><p>下一步就是根据 Draft 在实际游戏中布局。</p><p><span id="source-block-56Px6IMF9G9gnl3BSVCKDq"></span></p><h5 id="第一轮" tabindex="-1">第一轮 <a class="header-anchor" href="#第一轮" aria-label="Permalink to &quot;第一轮&quot;">​</a></h5><p>首先放置源和汇，以及直接连接源和汇的原件：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-edd6d4d22e064b37.q90-b132f874ac08915f.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="LqSjfxUrd0bWsxr2XDA6Zf"><p>step 1</p></div><p>然后考虑主链的放置：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c0e58cf38e27983c.q90-4a899754e9a1e6bd.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="SRq5GAHG4AiG9p8Zu6BuU8"><p>step 2</p></div><p>为了布局方便，我们拆开下侧的三汇流（经验证流量不变），得到：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ff889173e26b66d9.q90-7346467662fc572b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="76ar2gsl1y8wNqCRPleDBG"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2c152ddcb9542bce.q90-f110626c65a3809a.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="jwCzlI8G1gycgxqNyT2l6w"><p>step 3.2</p></div><p>继续拆分下侧三汇流：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9f8db3e6ea188340.q90-f06a7a4e0ca9099b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="3xEMQlKU5Y2tTygkPi5IO5"><p>step 4.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6694e35523aed094.q90-a4ae0147fd549257.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="ciPPIHvGx6qDWHfEi6vgSN"><p>step 4.2</p></div><p>这里有一个重要的观察：原件的朝向是可以在连接传送带的过程中动态修改的，即一开始的原件不应该拥有“朝向”这个属性</p><p>随后布局上侧汇流单元：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-aa304f3647f6ffeb.q90-1ccbf4ed31c566d7.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="qhJmout6Jgi8W97nJ219cz"><p>step 5</p></div><p>继续布局：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-81adb66e7f074d5d.q90-c1bea0c1892e2940.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="0VekmVzjrBjDbEUYn7Q07n"><p>step 6.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-796819c117d7fa9d.q90-1162a83edb598462.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="yurtIy4ealBxnxe0TNL6vQ"><p>step 6.2</p></div><p>此时发现左下角汇流器 → 右上角汇流器的连接已经无法建立，于是对布局进行修改：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-74af56a032e69980.q90-fa8dda4de129366c.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="hyBjG3YMQ4G9hwKyRMZFCB"><p>step 7.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-314f4c058d985449.q90-e2cc2b697ef3dc45.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="HZfOj6mEyi8gk6KGkS04bY"><p>step 7.2</p></div><p>接着完成最后的连接：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-55b86b0962b61116.q90-b6dfae1c76fd940b.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="lkguqyYn4PjZQedkl0fpeg"><p>step 8</p></div><p>于是我们得到了第一个可行的布局（面积 110，原件数 34，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-trnc79pKkAzcvat5lLwPk4"></span></p><h5 id="第二轮" tabindex="-1">第二轮 <a class="header-anchor" href="#第二轮" aria-label="Permalink to &quot;第二轮&quot;">​</a></h5><p>显然第一轮的结果看起来很丑陋，我们考虑回退并重新布局上侧：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5cb8abd6b0d33c7c.q90-dddecc18c51812c9.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="gCtHP9Ii5zAjWJXjxXtlTR"><p>step 1</p></div><p>继续：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-0b51f713ecc097dc.q90-62ca9a3c91276ecd.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="M3yqNmUq37TqEWB8T4JoLB"><p>step 2</p></div><p>上侧地方吃紧，考虑对图进行修改：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3348f44656e3e6fa.q90-8c8c073131fb0eba.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="VfRaDArr8CfUVcoNSNo4Xe"><p>step 3.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-abc81101899179b5.q90-df3c35e0a6263165.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="MTzRT8j69JFR2h3PxUkJSc"><p>step 3.2</p></div><p>继续：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8caea85c91e316b2.q90-f210f728f3bd2b07.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="5F9xN7hbpeMQOW823RLI7s"><p>step 4</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-04e7961f2ab79336.q90-11fcc3a56c338ac4.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="I29O44Z0BA0H8ErrNDqLN6"><p>step 5</p></div><p>第二个可行布局（面积 99，原件数 31，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-W3WqdXD4YJV2s5YwNQy4Rv"></span></p><h5 id="第三轮" tabindex="-1">第三轮 <a class="header-anchor" href="#第三轮" aria-label="Permalink to &quot;第三轮&quot;">​</a></h5><p>回退上侧：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cbdbdfe32553503b.q90-13dc059be757a0c9.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="Ke1GSBELTSu8dhMHKBWVcp"><p>step 1</p></div><p>拆分汇流器：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3ee61b72412b1958.q90-3720e4914eadfcc7.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="3dLtm8HZ35Edwsmuvr0BHZ"><p>step 2.1</p></div><p><img src="/endfield-skydoc/logistics/src/assets/images/img-84f3a8a6d9213725.q90-85761b021248f088.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="NfQKc3CrCMXzXRE1N1KATU"><p>step 2.2</p></div><p>最后完善一下：</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ef9d7525a6a8eae2.q90-35025034d085d9b2.webp" alt="针对理想系统的压缩算法"></p><div class="logistics-image-caption" data-source-block="AWb554q2yv7aMNachZbUlZ"><p>step 3</p></div><p>得到了一个还不错的整体布局（面积 88，元件数 32，经过流量仿真，周期流量确实是 325/799）</p><p><span id="source-block-Gu3I2yf3UWCp38vwbOqzfU"></span></p><h4 id="在这期间-我们做了哪些操作" tabindex="-1">在这期间，我们做了哪些操作？ <a class="header-anchor" href="#在这期间-我们做了哪些操作" aria-label="Permalink to &quot;在这期间，我们做了哪些操作？&quot;">​</a></h4><p>首先，我们通过“直觉”和“经验”设计了一个“看起来不错”的 Draft；</p><p>其次，我们基本只通过以下三个操作（当然，还有一些局部的修复动作以及回退）</p><ol><li><p><strong>修改拓扑</strong>：在 TopoFlow 图中拆分、合并节点，同时保持流量不变；</p></li><li><p><strong>放置元件</strong>：在 Draft 的引导下，寻找合适的位置放置元件/主轴</p></li><li><p><strong>连接传送带</strong>：连接已经放置了的原件</p></li></ol><p>得到了最终地蓝图；</p><p>值得注意的是，我们的<strong>每一次操作几乎都基于上一次操作的结果</strong>，整个布局过程是<strong>树状生长</strong>的（这也许也是随机/遗传算法效率较低的原因，毕竟我们的剪枝更激进）；</p><p><span id="source-block-NBrxgFGLhOL6s39emZ5HFt"></span></p><h3 id="将这些过程翻译成用于指导启发式搜索的搜索策略" tabindex="-1">将这些过程翻译成用于指导启发式搜索的搜索策略 <a class="header-anchor" href="#将这些过程翻译成用于指导启发式搜索的搜索策略" aria-label="Permalink to &quot;将这些过程翻译成用于指导启发式搜索的搜索策略&quot;">​</a></h3><p><span id="source-block-2M9WwkN54ZkkJuQHQK4oxZ"></span></p><h4 id="draft-生成" tabindex="-1">Draft 生成 <a class="header-anchor" href="#draft-生成" aria-label="Permalink to &quot;Draft 生成&quot;">​</a></h4><p>Draft 是一个基于拓扑排序生成的紧凑模板</p><p><span id="source-block-unCgOMXaO5XmPoCIoZHHA2"></span></p><h5 id="主轴发现" tabindex="-1">主轴发现 <a class="header-anchor" href="#主轴发现" aria-label="Permalink to &quot;主轴发现&quot;">​</a></h5><p>主轴有以下生成路径：</p><ol><li><p>从 splitter 的后继关系出发，枚举有向简单路径</p></li><li><p>从“允许直接接触”的后继关系出发（避免分流器 → 汇流器的优先级），枚举接触链</p></li></ol><p><span id="source-block-SMYQR2ywrfNO72ZlgS4WAj"></span></p><h5 id="回流分配" tabindex="-1">回流分配 <a class="header-anchor" href="#回流分配" aria-label="Permalink to &quot;回流分配&quot;">​</a></h5></div>',1)])])}const b=a(t,[["render",p]]);export{m as __pageData,b as default};
